"""
Files the un-segregated general-studies questions of Polity, History, Economy, Geography, Science & Technology, Society, Mental Ability and
Current Affairs under syllabus chapters (the same idea as env_chapters.py).

Only the coarse catch-all topics are re-filed (COARSE below); topics that already are real chapters (e.g. "Mughal Empire", "8. Indian Financial
System", "Physics: light & optics") are left alone, and the coarse History/Geography/Science/Economy questions are filed into those existing chapters
so nothing is duplicated. Reads the built bank (public/data/q/<subject>/*.json), writes data/subject-topics.json (question id -> [chapter, unit]);
scripts/prepare-content.mjs applies it and keeps the old topic as `srcTopic`.
Run `node scripts/prepare-content.mjs` first, then this script, then `node scripts/prepare-content.mjs` again.
"""
import collections, importlib.util, json, re, sys
from pathlib import Path

root = Path(__file__).resolve().parents[2]
spec = importlib.util.spec_from_file_location("gs_topics", root / "scripts/extract/gs_topics.py")
gs = importlib.util.module_from_spec(spec)
spec.loader.exec_module(gs)

