# Chapter names for the existing numbered economy topics (index names are truncated as stored).
ECONOMY_UNIT = {4: 4, 5: 5}

def score(text_q, text_o, text_e, pats, broad=()):
    out = []
    for _u, name, rx in pats:
        s = 2 * len(rx.findall(text_q)) + len(rx.findall(text_o)) + len(rx.findall(text_e))
        out.append(s * (0.6 if name in broad else 1.0))
    return out

def compile_(lst): return [(u, n, re.compile(r, re.I)) for u, n, r in lst]

GS_HIST_AM = [(None, n, re.compile(r, re.I)) for n, r in gs.T["gs-ancient-medieval"]]
GS_HIST_MOD = [(None, n, re.compile(r, re.I)) for n, r in gs.T["gs-modern-india"]]
GS_GEO = [(None, n, re.compile(r, re.I)) for n, r in gs.T["gs-geography"]]
GS_SCI = [(None, n, re.compile(r, re.I)) for n, r in gs.T["gs-science-tech"]]
TAX = {"polity": compile_(POLITY), "ap": compile_(AP_HISTORY), "society": compile_(SOCIETY), "mental": compile_(MENTAL), "current": compile_(CURRENT), "economy": compile_(ECONOMY)}
