THRESH = 1.2

def pick(q, kind, subject):
    text_q, text_o, text_e = q["question"], " ".join(q.get("options") or []), q.get("explanation") or ""
    if kind == "gs":
        if subject == "history":
            pats = GS_HIST_AM + GS_HIST_MOD
            fb = None
        elif subject == "geography":
            pats, fb = GS_GEO, gs.FALLBACK["gs-geography"]
        else:
            pats, fb = GS_SCI, gs.FALLBACK["gs-science-tech"]
        sc = score(text_q, text_o, text_e, pats, BROAD)
        best = max(sc)
        if best >= THRESH: return pats[sc.index(best)][1], pats[sc.index(best)][0]
        return (fb or "Indian history: other questions"), None
    pats = TAX[kind]
    sc = score(text_q, text_o, text_e, pats, BROAD)
    best = max(sc)
    if best >= THRESH:
        u, n, _ = pats[sc.index(best)]
        return n, u
    return {"polity": "Polity: other questions", "ap": "AP history: other questions", "society": "Society: other questions", "mental": "Reasoning & aptitude: other questions",
            "current": CURRENT_FALLBACK, "economy": "Indian economy: other questions"}[kind], None

def main(show=False):
    out, cnt, other = {}, collections.defaultdict(collections.Counter), []
    for subject, topics in COARSE.items():
        d = root / "public/data/q" / subject
        for f in sorted(d.glob("*.json")):
            for q in json.loads(f.read_text("utf8")):
                src = q.get("srcTopic") or q["topic"]
                kind = topics.get(src)
                if not kind: continue
                name, unit = pick(q, kind, subject)
                out[q["id"]] = [name, unit]
                cnt[subject][name] += 1
                if name.endswith("other questions"): other.append((subject, q))
    (root / "data/subject-topics.json").write_text(json.dumps(out, ensure_ascii=False, indent=0) + "\n", "utf8")
    for subject, c in cnt.items():
        n = sum(c.values()); o = sum(v for k, v in c.items() if k.endswith("other questions"))
        print(f"== {subject}: {n} questions re-filed into {len(c)} chapters ({100*o/n:.1f}% in 'other')")
        for name, v in sorted(c.items(), key=lambda kv: (-kv[1]))[:60]: print(f"  {v:4d}  {name}")
    if show:
        for subject, q in other[:60]: print("-", subject, "|", q["question"][:110].replace("\n", " "))

if __name__ == "__main__":
    main("--show-other" in sys.argv)
